import base64, gzip, json
from pathlib import Path

PAYLOAD = """"""
ROOT=Path(__file__).resolve().parents[1]
data=json.loads(gzip.decompress(base64.b64decode(PAYLOAD)).decode('utf-8'))
assert sum(len(v) for v in data['categories'].values())==999
(ROOT/'data'/'brand_catalog.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('999-brand catalog installed:', sum(len(v) for v in data['categories'].values()))
